  "about.founderHeading": "📖 Об основательнице",
  "about.founder.p1": "Привет! Я — Консепсьон, основательница Luminous StockHaven.",
  "about.founder.p2": "Я не из крупной технологической компании и не сижу в корпоративном офисе. Я — небольшой владелец розничного магазина, точно такой же, как вы. Я управляю пятью интернет-магазинами, специализирующимися на книгах и сделанных вручную аксессуарах для любителей книг.\nКак и многие независимые продавцы, я дошла до предела, пытаясь управлять запасами в нескольких точках, отслеживать ISBN издательств рядом с собственными артикулами ручной работы и обрабатывать заказы поставщикам в громоздких таблицах. Когда я искала приложение, которое мне поможет, я попробовала шесть разных вариантов. Каждое оказалось либо совершенно неполным, либо невероятно запутанным, либо хищническим — они брали сотни долларов в месяц за базовые инструменты.",
  "about.founder.p3": "Разочаровавшись в отрасли, которая выжимает независимых творцов, я решила создать собственное решение. Я построила Luminous StockHaven по необходимости — чтобы вести свой бизнес чисто, эффективно и со спокойной душой.",
  "about.founder.p4": "Я решила открыть эту платформу для публики по честной, доступной цене, потому что каждый небольшой продавец заслуживает инструментов, которые действительно работают, не ставя под угрозу его доход. Мы независимы, яростно защищаем наше сообщество и созданы продавцом для продавцов.",
