  "upgrade.doneUpgrade": "Теперь у вас Business.",
  "upgrade.doneDowngrade": "Переход на более низкий тариф запланирован.",
  "upgrade.doneTrial": "Ваш пробный период продолжается до {trialEnds}, затем Business начнётся по цене $29.99/месяц. Первое списание по Business произойдёт {firstCharge}.",
  "upgrade.doneUpgradeNow": "Business начинается сейчас по цене $29.99/месяц. Разница в цене будет включена в ваш следующий счёт — без немедленного списания.",
  "upgrade.doneDowngradeBody": "Вы сохраняете Business до {date}, затем Essentials начнётся по цене $14.99/месяц. Возврат средств за переход на более низкий тариф не производится.",
  "upgrade.planChangeNotCompleted": "Изменение тарифа НЕ было выполнено.",
  "upgrade.planChangeFallback": "Ничего не было изменено. Пожалуйста, попробуйте снова.",
