  "upgrade.previewUpgradeNote": "Переход на более высокий тариф никогда не перезапускает ваш бесплатный пробный период и никогда не создаёт вторую подписку.",
  "upgrade.previewDowngradeNote": "Переход на более низкий тариф вступает в силу в конце вашего оплаченного периода. Данные по утраченным функциям сохраняются, но становятся недоступными — они никогда не удаляются как побочный эффект перехода на более низкий тариф.",
  "upgrade.keepMyPlan": "Оставить мой тариф",
