  "billing.cancelError.signInRequired": "Чтобы отменить подписку, вам нужно войти в аккаунт. Пожалуйста, войдите и попробуйте снова.",
  "billing.cancelError.invalidRequest": "Мы не смогли определить, какую подписку отменить. Ничего не было изменено — пожалуйста, попробуйте снова или обратитесь в службу поддержки.",
  "billing.cancelError.businessIdRequired": "Мы не смогли определить, какую подписку отменить. Ничего не было изменено — пожалуйста, попробуйте снова или обратитесь в службу поддержки.",
  "billing.cancelError.subscriptionOwnerRequired": "Только владелец бизнеса может отменить эту подписку. Ничего не было изменено.",
  "billing.cancelError.billingRecordsNeedReview": "Ваши платёжные записи требуют проверки, прежде чем это можно будет отменить. Ничего не было изменено — пожалуйста, обратитесь в службу поддержки.",
  "billing.cancelError.complimentaryAccessProtected": "У этого рабочего пространства бесплатный доступ, поэтому платной подписки для отмены нет. Ничего не было изменено.",
  "billing.cancelError.noVerifiedSubscriptionRecord": "Мы не смогли найти подтверждённую подписку для этого бизнеса. Ничего не было изменено — пожалуйста, обратитесь в службу поддержки.",
  "billing.cancelError.purchaseContractMismatch": "Платёжная запись не соответствует этому бизнесу, поэтому мы не можем отменить подписку здесь. Ничего не было изменено — пожалуйста, обратитесь в службу поддержки.",
  "billing.cancelError.stripeNotConfigured": "Не удалось связаться с платёжной системой. Ничего не изменилось — пожалуйста, попробуйте снова или обратитесь в службу поддержки.",
  "billing.cancelError.subscriptionPaidThroughUnverified": "Мы не смогли подтвердить дату, до которой оплачена ваша подписка. Ничего не было изменено — пожалуйста, попробуйте снова или обратитесь в службу поддержки.",
  "billing.cancelError.alreadyEnded": "Эта подписка уже закончилась, поэтому отменять больше нечего.",
  "billing.cancelError.subscriptionEventHistoryIncomplete": "Ваша история платежей требует проверки, прежде чем это можно будет отменить. Ничего не было изменено — пожалуйста, обратитесь в службу поддержки.",
  "billing.cancelError.eventRequiresReview": "Ваша история платежей требует проверки, прежде чем это можно будет отменить. Ничего не было изменено — пожалуйста, обратитесь в службу поддержки.",
  "billing.cancelError.subscriptionCancellationUnavailable": "Отмену не удалось завершить. Ничего не было изменено — ваша подписка и доступ остались точно такими же, как были. Пожалуйста, попробуйте снова или обратитесь в службу поддержки.",
  "billing.readiness.ariaLabel": "Фактическая готовность оплаты Essentials",
  "billing.readiness.title": "Essentials — реальная проверка безопасности аккаунта",
  "billing.readiness.body": "Проверьте фактические записи о подписке и пробном периоде, ничего не покупая. Ваш бесплатный аккаунт Business и ваш образец пижамы останутся без изменений. Это не открывает оплату через Stripe, не списывает средства с карты и не изменяет тариф.",
  "billing.readiness.checking": "Проверка записей аккаунта…",
  "billing.readiness.inspect": "Проверить готовность оплаты (без списания)",
  "billing.readiness.unknown": "Проверка только для чтения не смогла установить готовность ({state}). Ничего не изменилось.",
  "billing.readiness.ready": "Оплата через Stripe готова — ключи, проверка вебхуков и аттестации подтверждены.",
  "billing.readiness.complimentaryProtected": "Ваше бесплатное рабочее пространство Business защищено. Оно не должно становиться платным тестовым аккаунтом Essentials.",
  "billing.readiness.environmentIncomplete": "Не удалось подтвердить все данные: учётные данные оплаты Stripe, проверку вебхуков или адрес возврата приложения. Оплата не может начаться.",
  "billing.readiness.ownerHasHistory": "У этого владельца есть предыдущие данные о подписке или пробном периоде. Вторая оплата не должна создаваться.",
  "billing.readiness.trialAlreadyUsed": "Ознакомительный пробный период уже был использован или зарезервирован. Повторный пробный период не может начаться.",
  "billing.readiness.trialEligibilityUnverified": "Право на однократный пробный период не подтверждено для этого владельца. Оплата остаётся заблокированной.",
  "billing.readiness.testModeUnverified": "Записи аккаунта читаются, но безопасное ограничение тестового режима Stripe и выполнение платного продления не подтверждены. Оплата остаётся заблокированной.",
  "billing.readiness.entitlementNotUnique": "Информация о существующем тарифе отсутствует или неоднозначна. Оплата не может начаться.",
