  "billing.readiness.billingHistoryIncomplete": "Полную историю владельца не удалось подтвердить. Оплата не может начаться.",
  "billing.readiness.ownershipMismatch": "Владение аккаунтом или платёжные записи требуют проверки, прежде чем можно будет начать любую подписку.",
  "billing.readiness.catalogUnverified": "Утверждённое серверное определение оплаты — $14.99/месяц — требует проверки.",
  "billing.readiness.auditUnavailable": "Проверка сервера только для чтения была недоступна. Оплаты или изменения аккаунта не произошло.",
  "billing.dryRun.ariaLabel": "Симуляция тестового перехода на более высокий тариф",
  "billing.dryRun.title": "Essentials → Business — практическая симуляция",
  "billing.dryRun.body": "Отработайте предлагаемые правила перехода на более высокий тариф, используя полностью вымышленные записи в этом браузере. Это не читает и не изменяет ваш реальный образец TEST — пижамные штаны, ваше текущее рабочее пространство Business, Stripe, пробные периоды, подписки или остатки.",
  "billing.dryRun.runButton": "Запустить локальную симуляцию перехода (без списания)",
  "billing.dryRun.passed": "Вымышленный сценарий прошёл локальные проверки",
  "billing.dryRun.blocked": "Вымышленный сценарий был заблокирован",
  "billing.dryRun.example": "Пример: Essentials ($14.99/месяц) → Business ($29.99/месяц), до применимых налогов.",
  "billing.dryRun.preserved": "Та же подписка сохранена, один первоначальный пробный период сохранён, а симулированные остатки пижамы не изменились. Примерный клиент остаётся на Essentials до тех пор, пока реальное платное продление, подтверждённое провайдером, не оправдает изменение доступа.",
  "billing.dryRun.limitations": "Локальная симуляция не тестирует изменения подписки в Stripe, платёж, вебхук, расчёт с учётом налогов, действующую подписку или ваши фактические записи бизнеса.",
  "billing.dryRun.noRecordsChanged": "Никакие записи не были изменены.",
