  "payroll.dd.steps.body": "1. Вам нужен бизнес-счёт в банке, который может отправлять платежи ACH. 2. Соберите подписанную форму разрешения у каждого члена команды — аннулированный чек поможет проверить номера. 3. Отправляйте зарплату за 2–3 рабочих дня до дня выплаты, чтобы деньги пришли вовремя. 4. В большинстве штатов требуется письменное согласие члена команды. Это приложение собирает формы и проводит вас по шагам — фактическая отправка денег происходит через ваш банк.",
  "payroll.dd.steps.title": "Как работает прямой депозит",
