  "training.warningSentOn": "Предупреждение отправлено {date}",
  "auth.sameEmailNotice": "У вас уже есть наше приложение из Google Play или App Store? Используйте здесь тот же адрес электронной почты — тот, с которым вы входите в приложение, — чтобы ваш магазин и ваши остатки перешли с вами. Другой адрес электронной почты начинает совершенно новый, пустой магазин.",
