  "plansLib.includes.bulkEdit": "Массовое редактирование и удаление — обновляйте или удаляйте много товаров сразу",
  "print.templateShipping": "Транспортная этикетка",
  "print.templateShippingHint": "Этикетка 4×6 с именем и адресом покупателя",
