  "print.recipientNameLabel": "Имя получателя",
  "print.recipientAddressLabel": "Адрес получателя",
  "print.senderAddressLabel": "Ваш адрес (отправитель)",
  "print.shippingNote": "Если в заказе есть адрес доставки, он подставится из заказа. То, что вы впишете здесь, напечатается один раз и никогда не сохранится.",
  "print.carrier.title": "Этикетка вашего перевозчика",
  "print.carrier.desc": "Покупайте почтовую отправку у перевозчика, как вы делаете сегодня, — это приложение никогда не продаёт почтовые услуги, поэтому цена, которую вы платите, всегда является ценой самого перевозчика. Сохраните файл этикетки здесь, и он навсегда останется на этом заказе: ваша запись, под рукой на всякий случай.",
  "print.carrier.none": "Для этого заказа ещё не сохранена этикетка перевозчика.",
