  "print.carrier.pdfHint": "Эта этикетка — PDF. Она открывается в своём настоящем размере — печатайте из просмотрщика, и она выйдет ровно 4×6.",
  "print.carrier.pickOrderFirst": "Выберите заказ выше, а затем сохраните здесь его этикетку перевозчика.",
