  "print.style.title": "Стиль документов",
  "print.style.desc": "Сделайте ваши документы вашими. Эти настройки одевают ваш счёт, чек, упаковочный лист, документы возврата, листы товаров, листы подсчёта и списки отбора — и запоминаются для вашего бизнеса.",
  "print.style.logoLabel": "Ваш логотип",
