  "profile.ownerDesc": "Ваша фотография и имя, под которым вас знает ваша команда. Ваша собственная фотография отображается сразу — одобрение не требуется.",
  "profile.memberDesc": "Ваша фотография отображается рядом с вашим именем после того, как владелец её одобрит. До этого отображаются только ваши инициалы.",
