  "training.lessons.your-profile-photo.title": "Ваша фотография профиля",
  "training.lessons.your-profile-photo.step1": "Ваша фотография появляется рядом с вашим именем в верхней части приложения, на странице Сотрудники и рядом с вашими сообщениями — после того, как владелец её одобрит. До этого отображаются только ваши инициалы.",
  "training.lessons.your-profile-photo.step2": "Откройте Настройки и найдите Ваша фотография профиля. Выберите свою фотографию и отправьте её. Она отправляется владельцу на одобрение — она нигде не появляется, пока ожидает.",
  "training.lessons.your-profile-photo.step3": "Когда владелец её одобрит, ваш колокольчик зазвенит и ваша фотография начнёт отображаться. Если она не одобрена, выберите другую фотографию и отправьте её вместо неё.",
  "training.lessons.your-profile-photo.step4": "Смена фотографии работает так же: новая ожидает одобрения, а ваша текущая фотография остаётся на месте, пока новая не будет одобрена. Если изменение не одобрено, вы сохраняете другую фотографию.",
  "training.lessons.owner-profile-photos.title": "Фотографии профиля и ваше имя",
  "training.lessons.owner-profile-photos.step1": "Фотография каждого человека отображается рядом с его именем в верхней части приложения, на вашей странице Сотрудники и рядом с его сообщениями. Фотография участника команды нигде не появляется, пока вы её не одобрите — одобрение принадлежит только вам, и никто не может одобрить собственную фотографию.",
  "training.lessons.owner-profile-photos.step2": "Когда кто-то отправляет фотографию, ваш колокольчик звенит. Откройте страницу Сотрудники, чтобы увидеть её, затем выберите Одобрить или Не одобрять. Если вы её не одобрите, человеку сообщат, что нужно выбрать другую фотографию.",
  "training.lessons.owner-profile-photos.step3": "Если человек меняет свою фотографию, новая ожидает вашего одобрения таким же образом. Его текущая фотография остаётся на месте, пока ожидает — и остаётся, если вы не одобрите изменение.",
  "training.lessons.owner-profile-photos.step4": "Ваша собственная фотография не требует одобрения: установите её в Настройках, в разделе Ваша фотография профиля. На той же карточке находится ваше имя — имя, которое вы там установите, заменяет слово Владелец везде, где его видит ваша команда, в приложении и в Сообщениях.",
  "payroll.dd.corrected": "Исправленная форма",
