  "payroll.dd.correctionNotice": "Владелец вернул вам форму, чтобы вы её исправили. Проверьте каждую цифру, подпишите и отправьте снова.",
  "payroll.dd.correctionWaiting": "Возвращено — ожидание исправленной формы",
  "payroll.dd.fixHelp": "Если цифра неверна, исправьте реквизиты и отправьте форму снова. Ваша новая подписанная форма заменяет старую, и владелец узнает, что она была исправлена.",
