  "training.lessons.owner-dd-setup.step5": "Приходит запечатанная подписанная форма: из строки человека в разделе «Расчёт зарплаты» вы можете открыть её, чтобы прочитать полные номера, распечатать или сохранить копию — редактировать её нельзя никогда. Если номер выглядит неверно, верните форму: человек исправит её и подпишет заново сам, его исправленная форма заменит старую, а прежняя останется в записи с датой замены.",
