  "staffLib.area.clockAccess": "Табель и вызовы",
  "staff.memberDialog.clockAccessHint": "Только для менеджеров — две отдельные отметки. «Табель команды и пропущенные уходы» даёт этому менеджеру видеть записи времени команды и исправлять записи времени на странице «Сотрудники». «Вызовы» даёт этому менеджеру открывать окна вызова, давая человеку работать, когда у него нет смены. Для обычных сотрудников эти отметки ничего не дают.",
