  "apiErrors.clockFix.invalidTime": "Укажите каждое время как действительные дату и время.",
  "apiErrors.notFound.timeEntryFound": "Запись времени не найдена.",
  "training.lessons.mgr-clock-callin.title": "Вызовы и исправления времени",
  "training.lessons.mgr-clock-callin.step1": "Владелец может дать менеджеру две отдельные отметки. «Вызовы» позволяют открыть окно вызова для сотрудника, а «Табель команды и пропущенные уходы» позволяет видеть табель команды и исправлять записи времени на странице «Сотрудники». Каждая отметка работает сама по себе — менеджер может иметь одну без другой.",
  "training.lessons.mgr-clock-callin.step2": "Окно вызова позволяет человеку войти и отметиться, когда ни одна смена его не покрывает. Откройте его на странице «Сотрудники», на карточке «Вызовы и пропущенные уходы».",
  "training.lessons.mgr-clock-callin.step3": "Окно остаётся открытым, пока этот человек не отметит уход, — после этого действует обычный 10-минутный льготный период перед выходом — или пока вы или владелец не закроете его раньше. Само оно не закрывается.",
  "training.lessons.mgr-clock-callin.step4": "Когда кто-то забывает отметить уход, его запись помечается на странице «Сотрудники» и в расчёте зарплаты, как только запланированная смена заканчивается, а вы и владелец получаете уведомление. Запись продолжает считаться, пока её не исправят.",
  "training.lessons.mgr-clock-callin.step5": "Исправьте запись на странице «Сотрудники»: укажите приход, уход и время перерывов. Менеджер исправляет только записи сотрудников — записи менеджера исправляет владелец.",
  "staffLib.perm.staffDocuments": "Документы персонала",
  "staffLib.area.documentsAccess": "Документы персонала",
  "staff.memberDialog.documentsAccessHint": "Только для менеджеров — с этой отметкой менеджер может открывать папки документов сотрудников: бумаги, которые хранятся на каждого человека, например формы W-4, заявления о приёме на работу и копии удостоверений личности. Сначала потребуется подтверждение — в этих папках есть номера социального страхования и даты рождения. Для обычных сотрудников эта отметка ничего не делает.",
  "staff.documentsWarning.body": "Этот человек сможет видеть конфиденциальную информацию о ваших сотрудниках, включая номера социального страхования и даты рождения.",
