  "plansLib.businessIncludes.xstoreMessages": "Сообщения между магазинами — вся ваша команда, во всех ваших компаниях",
  "xstore.title": "Сообщения между магазинами",
  "xstore.help": "Все люди в этом аккаунте, из всех ваших компаний, в одном почтовом ящике. Пишите любому из них здесь — текстом или голосом, с отметками о доставке и прочтении. Ваши Сообщения внутри магазина остаются как есть.",
  "xstore.empty": "Разговоров пока нет. Начните один с помощью «Новое сообщение».",
  "xstore.noPeople": "Пока больше некому писать. Люди появляются здесь, как только присоединяются к одной из ваших компаний и входят в систему.",
  "xstore.deliveredLabel": "Доставлено",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Сообщения между магазинами входят в план Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Этот человек не входит в этот аккаунт.",
  "training.lessons.owner-xstore-messages.title": "Сообщения между вашими магазинами, для владельцев",
  "training.lessons.owner-xstore-messages.step1": "Сообщения между магазинами — это второй почтовый ящик, отдельный от Сообщений. Сообщения предназначены для магазина, в котором вы находитесь; эта дверь открывает доступ ко всем людям в вашем аккаунте, в каждой компании, которой вы владеете, — до пяти.",
  "training.lessons.owner-xstore-messages.step2": "Откройте «Сообщения между магазинами» в меню и начните разговор с любым человеком из списка. В списке отображается каждый член команды из всех ваших компаний, который вошёл в систему, вместе с магазинами, в которых он работает.",
  "training.lessons.owner-xstore-messages.step3": "Фотографии идут вместе: каждый человек показывает свою одобренную фотографию профиля или свои инициалы, если фотографии нет. Каждое сообщение содержит дату и время его отправки.",
  "training.lessons.owner-xstore-messages.step4": "Под своими сообщениями вы можете видеть «Доставлено», как только сообщение приходит, и «Прочитано», как только другой человек открывает разговор. Голосовые сообщения здесь тоже работают, точно так же, как в Сообщениях.",
  "training.lessons.owner-xstore-messages.step5": "Разговоры здесь являются личными для двух участвующих в них людей. Ваш контроль над Сообщениями внутри магазина не распространяется на другие магазины.",
  "training.lessons.mgr-xstore-messages.title": "Сообщения между вашими магазинами, для менеджеров",
  "training.lessons.mgr-xstore-messages.step1": "Сообщения между магазинами охватывают всех людей в этом аккаунте, во всех компаниях — а не только магазин, в котором вы находитесь. Они находятся в меню, отдельно от Сообщений.",
  "training.lessons.mgr-xstore-messages.step2": "Начните разговор из списка: там есть каждый член команды, который вошёл в систему, а рядом с его именем — магазины, в которых он работает.",
  "training.lessons.mgr-xstore-messages.step3": "Отправьте текст или запишите голосовое сообщение. Перед отправкой голосового сообщения вы можете прослушать его, удалить или отправить — так же, как в Сообщениях.",
  "training.lessons.mgr-xstore-messages.step4": "Ваши сообщения показывают «Доставлено», когда они приходят, и «Прочитано», когда другой человек открывает разговор. Фотография рядом с каждым именем — это одобренная фотография профиля этого человека.",
  "training.lessons.staff-xstore-messages.title": "Сообщения между вашими магазинами",
  "training.lessons.staff-xstore-messages.step1": "Сообщения между магазинами — это место, где вы можете связаться с любым человеком в этом аккаунте, в любой компании владельца — вопросу для другого магазина больше не нужно ждать.",
  "training.lessons.staff-xstore-messages.step2": "Откройте их в меню, выберите человека и напишите. Если нужного вам человека нет в списке, он ещё не вошёл в систему — он появится, как только войдёт.",
  "training.lessons.staff-xstore-messages.step3": "Здесь вы также можете отправлять голосовые сообщения: запишите, прослушайте, а затем отправьте или удалите. Каждое сообщение показывает дату и время его отправки.",
  "training.lessons.staff-xstore-messages.step4": "Когда вы отправляете сообщение, оно показывает «Доставлено», как только приходит, и «Прочитано», как только другой человек открывает разговор. Разговор является личным для вас и другого человека.",
