  "plansLib.businessIncludes.restaurantOps": "Работа ресторана — счета поставщиков с трёхсторонней сверкой, журнал списаний, сроки годности и матрица аллергенов",
  "plansLib.businessIncludes.restaurantDaily": "Ежедневные инструменты ресторана — журналы температур, доска закончившихся блюд, листы заготовок, инженерия меню, расхождения и экспорт для бухгалтерии",
  "plansLib.businessIncludes.restaurantKitchen": "Ресторан, кухня и рецепты — рецепты с автоматическим списанием ингредиентов и настоящей себестоимостью блюд, листы подготовки, серийное производство и инженерия меню",
  "plansLib.businessIncludes.restaurantStock": "Ресторан, склад и заказы — уровни запаса (пар), руководство по заказам поставщикам и перемещения между точками, а также листы подсчёта в порядке полок",
  "plansLib.businessIncludes.restaurantMoney": "Ресторан, счета и деньги — счета поставщиков с трёхсторонней сверкой, оповещения о ценах, расхождения и экспорт в бухгалтерию, а также кредитные ноты поставщиков",
  "plansLib.businessIncludes.restaurantSafety": "Ресторан, безопасность пищи — журналы температур, сроки годности в порядке «раньше истекает — раньше использовать», этикетки с датами и матрица аллергенов и заполненные журналы температур для архива безопасности пищевых продуктов",
