  "exportsLib.restaurantLedger.title": "Книга ресторана",
  "exportsLib.restaurantLedger.description": "Принятые закупки, списания, питание персонала и расход по рецептам в одной книге: раздел, дата, позиция, количество, себестоимость за единицу, общая себестоимость и ссылка.",
