  "storefronts.ebayDesc": "Подключите свою витрину eBay один раз. Когда товар продаётся на eBay, его количество здесь уменьшается само, а продажа записывается в ваши движения — так же, как если бы его отсканировали на выбытие. Продажи идут только в одну сторону: из eBay в приложение.",
