  "apiErrors.checklistsManage": "Только владелец, или человек, которому владелец дал отметку шаблонов списков, может менять шаблоны списков.",
  "apiErrors.checklistProof": "Этому пункту нужно его подтверждение, прежде чем его можно будет отметить.",
  "apiErrors.checklistName": "Дайте списку название.",
  "apiErrors.checklistItems": "Добавьте в список хотя бы один пункт.",
  "apiErrors.checklistUntick": "Только человек, отметивший этот пункт, менеджер или владелец может снять отметку.",
  "training.lessons.staff-checklists.title": "Работа со списком",
  "training.lessons.staff-checklists.step1": "Контрольные списки — это списки, на которых работает ваше дело: открытие, закрытие, уборка и всё, что настроит владелец. Ищите их в разделе «Контрольные списки»: сегодняшние списки сверху, готовые к отметкам.",
  "training.lessons.staff-checklists.step2": "Отмечайте пункт, когда вы его действительно выполнили. Каждая отметка записывает, кто сделал и когда, чтобы следующий человек — и владелец из дома — видели, что сделано, а что ещё нет.",
  "training.lessons.staff-checklists.step3": "Некоторые пункты просят подтверждение, прежде чем их можно отметить: фото готовой работы, сканирование кода или введённую температуру. Сначала добавьте подтверждение, затем отмечайте — без него пункт не отметится.",
  "training.lessons.staff-checklists.step4": "Отметили что-то по ошибке? Снимите отметку — но только свои. Менеджер или владелец может снять любую, потому что отметка — это запись с именем.",
  "training.lessons.staff-checklists.step5": "Для работы со списком разрешение не нужно никогда. Создавать шаблоны и выбирать, кому они назначены, — дело владельца или человека, которому владелец дал отметку шаблонов списков.",
