  "foodSafety.mock.title": "Учебная проверка",
  "foodSafety.mock.subtitle": "Пройдите по кухне так, как это сделал бы инспектор, до того, как это сделает инспектор.",
  "foodSafety.mock.intro": "Начните учебную проверку и отмечайте каждый пункт на странице чек-листов по мере проверки. Каждая отметка записывает, кто проверял и когда, — исправляйте найденное по ходу, и досье покажет работу.",
  "foodSafety.mock.startButton": "Начать сегодняшнюю учебную проверку",
  "foodSafety.mock.startFailed": "Учебную проверку не удалось начать.",
