  "foodSafety.mock.openChecklists": "Открыть чек-листы",
  "foodSafety.mock.item1": "Холодильники, морозильники и горячее хранение в своих безопасных диапазонах, и журнал температур заполнен.",
  "foodSafety.mock.item2": "Проверки охлаждения и повторного разогрева записаны, с корректирующим действием там, где показание промахнулось.",
  "foodSafety.mock.item3": "Дезинфицирующий раствор смешан в правильной крепости, и его проверка записана.",
  "foodSafety.mock.item4": "Каждый пищевой сертификат действует, и продления идут для тех, что скоро истекают.",
  "foodSafety.mock.item5": "Паспорта безопасности стоят на полке, где их может читать вся команда.",
  "foodSafety.mock.item6": "Датированная пища промаркирована и используется в порядке истечения: сначала та, что истекает раньше.",
  "foodSafety.mock.item7": "Аллергены отмечены на каждом блюде в матрице аллергенов.",
  "foodSafety.mock.item8": "Журнал отходов актуален, с причиной для всего выброшенного.",
  "training.lessons.staff-food-safety.title": "Ведение досье безопасности пищи",
  "training.lessons.staff-food-safety.step1": "Досье безопасности пищи живёт на полке «Безопасность пищи» ресторанного уголка: журналы температур, журналы охлаждения, повторного разогрева и дезинфекции, сертификаты, паспорта безопасности и пакет для проверки.",
  "training.lessons.staff-food-safety.step2": "Показание вне диапазона не завершено, пока его заметка не скажет, что вы сделали: снова охладили, снова разогрели, переделали дезинфектант, выбросили. Нет заметки — нет сохранения: запись не засчитывается.",
  "training.lessons.staff-food-safety.step3": "Записывайте проверки охлаждения, повторного разогрева и дезинфекции как температуры: что проверяли, показание и корректирующее действие при промахе.",
  "training.lessons.staff-food-safety.step4": "Сертификаты предупреждают до истечения. Когда ваш предупредит, скажите владельцу — и любой может в любое время читать паспорта безопасности на их полке.",
  "training.lessons.staff-food-safety.step5": "Перед проверкой — или в любое время — запустите учебную проверку с полки «Безопасность пищи» и напечатайте готовый к проверке пакет на даты инспектора.",
