  "training.lessons.staff-equipment.title": "Карточки оборудования и как сообщить о поломке",
  "training.lessons.staff-equipment.step1": "У каждой машины вашего бизнеса есть своя страница в разделе «Оборудование»: когда она куплена, когда кончается гарантия, кто её обслуживает и всё, что с ней случилось.",
  "training.lessons.staff-equipment.step2": "Когда что-то ломается, сообщите об этом на самой машине. Скажите, что сломалось, и по возможности добавьте фотографию проблемы — сообщение попадёт в историю машины с вашим именем и временем.",
  "training.lessons.staff-equipment.step3": "Сообщить о поломке можно только если владелец дал вам отметку для сообщений о поломках. Если кнопки нет, скажите владельцу или менеджеру, и они откроют вам дверь.",
  "training.lessons.staff-equipment.step4": "У задач обслуживания — чистка, удаление накипи, сервис — есть сроки. Страница оборудования показывает, что к сроку и что просрочено, чтобы ничего не ускользнуло молча.",
  "training.lessons.staff-equipment.step5": "Ремонты и их стоимость записывает владелец или менеджер. Когда ремонт записан по вашему сообщению, поломка значится в истории машины как отремонтированная.",
  "nav.tipPooling": "Общий фонд чаевых",
