  "training.lessons.owner-tip-pooling.title": "Фонд чаевых и учёт чаевых",
  "training.lessons.owner-tip-pooling.step1": "Откройте «Ресторан», затем «Команда и место», затем «Общий фонд чаевых». Только владелец видит настройку фонда, доли и записи.",
  "training.lessons.owner-tip-pooling.step2": "Выберите, как делится фонд: по часам, по проценту роли или по баллам. Приложение делит по расписанию и уже отмеченным часам.",
  "training.lessons.owner-tip-pooling.step3": "Выберите период, введите сумму фонда, просмотрите распределение и сохраните его. Сохранённые доли попадают в предпросмотр зарплаты за этот период.",
  "training.lessons.owner-tip-pooling.step4": "Опубликуйте сохранённое распределение, когда будете готовы, — сотрудник тогда увидит только свою долю, а до публикации — ничего.",
  "training.lessons.owner-tip-pooling.step5": "Ведите учёт чаевых по ходу дела: по каждому человеку и периоду — сообщённые чаевые, а годовой учёт превращает расчёт 8 % в готовые для формы итоги. Приложение только хранит записи; оно ничего не подаёт.",
