  "apiErrors.laborOwner": "Только владелец может задавать числа наблюдения за трудом.",
  "apiErrors.laborSettings": "Проверьте числа наблюдения за трудом и попробуйте ещё раз.",
  "training.lessons.owner-labor-warnings.title": "Настройка предупреждений по труду",
  "training.lessons.owner-labor-warnings.step1": "Откройте расписание и найдите числа наблюдения. Каждое число там — ваше, для вашего места.",
  "training.lessons.owner-labor-warnings.step2": "Задайте недельные часы, с которых для вас начинается переработка, и как близко можно подойти, прежде чем приложение предупредит.",
  "training.lessons.owner-labor-warnings.step3": "Задайте, когда в смене ожидается перерыв и сколько он должен длиться, а также самое раннее начало и самое позднее окончание смен.",
  "training.lessons.owner-labor-warnings.step4": "Стройте неделю как обычно. Предупреждения появляются в расписании, когда часы приближаются к вашим линиям — до того, как их перейдут.",
  "training.lessons.owner-labor-warnings.step5": "Пока команда отмечается на входе и выходе, то же наблюдение проходит по уже отработанным часам, включая перерывы, которые не взяли.",
  "training.lessons.owner-labor-target.title": "Строить неделю против цели по труду",
  "training.lessons.owner-labor-target.step1": "Откройте «Цель по труду» на полке «Команда и место» в Ресторанном уголке.",
  "training.lessons.owner-labor-target.step2": "Введите вашу цель по труду в процентах и продажи, которые ожидаете за неделю.",
  "training.lessons.owner-labor-target.step3": "Стройте неделю в расписании. Прогноз затрат на труд и % обновляются из смен и ставок, уже сохранённых в приложении.",
  "training.lessons.owner-labor-target.step4": "Когда прогноз % труда проходит вашу цель, страница говорит об этом простыми словами, с часами и затратами за этим.",
  "training.lessons.owner-labor-target.step5": "Печатайте неделю со страницы, когда хотите её на бумаге, — напечатанный лист — тот же документ, что вы видите на экране.",
  "nav.cateringEvents": "Кейтеринг и мероприятия",
