  "apiErrors.waitlistInvalid": "Проверьте данные листа ожидания и попробуйте ещё раз.",
  "training.lessons.owner-reservations.title": "Приём бронирований и ведение листа ожидания",
  "training.lessons.owner-reservations.step1": "Откройте «Бронирования» на полке «Зал и гости» Ресторанного уголка. Книга хранит каждое бронирование; лист ожидания под ней хранит гостей без брони на этот вечер.",
  "training.lessons.owner-reservations.step2": "Добавьте бронирование с датой и временем, именем и размером компании, номером телефона и столом или зоной своими словами. Отметьте то, что должна знать кухня, — аллергию, детский стульчик, годовщину.",
  "training.lessons.owner-reservations.step3": "Спросите гостя, хочет ли он напоминание, и ставьте отметку только когда он говорит «да». Напоминания идут по почте и, когда СМС настроены, по СМС. Запишите любой уже полученный депозит — сколько и как — только как запись.",
  "training.lessons.owner-reservations.step4": "Ведите книгу весь вечер: отмечайте каждую компанию как посаженную, не пришедшую или отменённую. Отправляйте список на сегодня команде из книги, чтобы все работали по одной странице.",
  "training.lessons.owner-reservations.step5": "Для гостей без брони добавьте компанию в лист ожидания с названным ожиданием. Когда их стол будет готов, нажмите «Стол готов» — дать номер для этого сообщения и есть «да» гостя.",
