  "training.lessons.owner-standing-orders.title": "Постоянные заказы и сравнение цен поставщиков",
  "training.lessons.owner-standing-orders.step1": "Откройте «Постоянные заказы» на полке «Запас и заказы» Уголка ресторана. Ваши повторяющиеся заказы живут здесь, а под ними — книга цен поставщиков.",
  "training.lessons.owner-standing-orders.step2": "Настройте постоянный заказ один раз: дайте ему название, выберите поставщика и день, на который он рассчитан, и добавьте строки основ с количествами, которые вы обычно заказываете.",
  "training.lessons.owner-standing-orders.step3": "Когда день наступит, нажмите «Создать черновик этой недели». Приложение запишет черновик заказа на закупку в раздел «Закупки» по последней цене этого поставщика из книги — проверьте его, измените всё нужное и отправьте сами. Приложение никогда не отправляет заказ само.",
  "training.lessons.owner-standing-orders.step4": "Читайте книгу цен перед заказом: один ингредиент, последняя цена каждого поставщика рядом, самая дешёвая первой, с датой и указанием, из счёта цена или из заказа.",
  "training.lessons.owner-standing-orders.step5": "Держите книгу честной, внося счета поставщиков по мере их поступления, — каждая новая цена попадает в книгу, и следующий черновик рассчитывается по ней.",
  "nav.productionOrder": "Заказ по производству",
  "restaurant.doorProductionOrder": "Заказ по производству — превратите производственную партию или банкетное событие в нужный ему заказ ингредиентов",
