  "training.lessons.owner-production-order.title": "Заказ по производству и листы подготовки, которые заполняются сами",
  "training.lessons.owner-production-order.step1": "Откройте «Заказ по производству» на полке «Склад и заказы» Уголка ресторана. План производства — производственная партия или банкетное событие — становится здесь заказом ингредиентов.",
  "training.lessons.owner-production-order.step2": "Выберите план: рецепт и число партий для производства или одно из ваших забронированных банкетных событий. Нажмите «Рассчитать заказ».",
  "training.lessons.owner-production-order.step3": "Приложение разворачивает рецепты, вычитает то, что уже на складе, и округляет остальное вверх до размера упаковки, сгруппировав по поставщикам — форма руководства по заказу.",
  "training.lessons.owner-production-order.step4": "Нажмите «Создать черновики заказов», и по одному черновику заказа на закупку на поставщика попадёт в «Закупки». Проверьте и отправьте их сами — приложение никогда не отправляет заказ само.",
  "training.lessons.owner-production-order.step5": "На странице подготовки лист заполняется сам: предлагаемые партии берутся из ваших уровней par, бронирований и событий и того, что уже подготовлено, — предложение показывается, и ничего не меняется, пока вы не запустите партию.",
  "nav.barCounting": "Подсчёт бара",
