  "barCounting.title": "Подсчёт бара",
  "barCounting.subtitle": "Считайте открытое по зонам хранения. Двигайте ползунок, насколько полной выглядит открытая бутылка, — в десятых — и записывайте кеги так же. Полные бутылки и кеги считаются целыми.",
  "barCounting.offTitle": "Подсчёт бара выключен",
  "barCounting.offBody": "Подсчёт бара остаётся скрытым, пока владелец его не включит. Включайте, только если у этого бизнеса есть бар, — он появляется на полке «Запасы и заказы».",
