  "barCounting.varianceNote": "Сохранённый подсчёт бара — это сессия подсчёта: его расхождения с учётом — фактическая сторона отклонения теории от факта.",
  "apiErrors.barCountingForbidden": "Только владелец может включать или выключать подсчёт бара.",
  "apiErrors.barCountingCountForbidden": "Только владелец, менеджер или человек с правом подсчёта может сохранять подсчёт бара.",
