  "apiErrors.barCountingOff": "Подсчёт бара не включён для этого бизнеса.",
  "training.lessons.owner-bar-counting.title": "Подсчёт бара: неполные бутылки и кеги",
  "training.lessons.owner-bar-counting.step1": "Включите подсчёт бара на полке «Запасы и заказы» — он остаётся скрытым, пока вы этого не сделаете, поэтому бизнес без бара никогда его не видит. Переключатель принадлежит только владельцу.",
  "training.lessons.owner-bar-counting.step2": "Откройте «Подсчёт бара» и выберите зону хранения, в которой вы стоите. Лист показывает, что хранится в зоне, с учётным количеством рядом с каждой бутылкой и кегом.",
  "training.lessons.owner-bar-counting.step3": "В каждой строке укажите, бутылки это или кег, введите полные, затем двигайте ползунок, насколько полной выглядит открытая, — в десятых, судя по её картинке. Посчитанное число — полные плюс десятые открытой.",
  "training.lessons.owner-bar-counting.step4": "Сохраните подсчёт бара. Он попадает в «Подсчёты» как обычная сессия подсчёта — отправьте его на проверку и примените там, и полка встанет на то, что вы посчитали.",
  "training.lessons.owner-bar-counting.step5": "Расхождения, которые находит подсчёт бара, питают отклонение теории от факта, поэтому бутылка, которой постоянно не хватает, покажется там. Печатайте лист подсчёта с этой страницы, когда нужен подсчёт на бумаге.",
